import{n as e}from"./QTnfLwEv.js";var t=e({default:()=>n}),n={"faq.answer.cloud-hosting.what-is-it":`<p><a target="_blank" href="https://www.hostinger.com/in/tutorials/what-is-cloud-hosting">Cloud hosting is</a> a faster, stronger, and more reliable alternative to shared hosting.</p><p>Hostinger’s managed cloud hosting offers 4X more speed and 20X more resources compared to traditional web hosting. It’s also fully managed – meaning that we take care of all the technical stuff, so you can focus on scaling your projects.</p><p>It’s the perfect solution for website owners looking for the power and stability of a virtual private server (VPS), without the complexity of managing one.</p>`,"faq.answer.cloud-hosting.vps-vs-cloud":`<p><a target="_blank" href="{link}">VPS hosting</a> provides dedicated resources and root access, ensuring rock-solid performance and allowing you to self-manage the server and customise your hosting environment to your specific needs. Since it’s a self-managed service, VPS hosting requires more technical skills.</p><p>Meanwhile, cloud hosting combines the power of a VPS and the simplicity of managed web hosting. It features a pre-built environment and an easy-to-use control panel, so you can enjoy a fast and secure website without dealing with the complexity of VPS hosting.</p><p>Our cloud hosting options also come with an integrated content delivery network (CDN). It automatically stores copies of your site’s content across a global network of servers, improving site performance by 40%.</p><p>With VPS hosting, your website data will be stored on a single physical server.</p>`,"faq.answer.cloud-hosting.node-js":`<p>Our cloud hosting platform currently doesn’t support Node.js. But you can still create and host your Node.js applications with our <a target="_blank" href="{link}">VPS hosting plans</a>.</p>`,"faq.answer.cloud-hosting.why-to-get":`<p>Whether you’re running an eCommerce store that sells hundreds of products, or a business site handling hundreds of thousands of visitors each month, cloud server hosting has the computing power to maintain high performance and uptime, while still being easy to use.</p><p>It’s also the right choice for web developers and agencies that manage multiple clients and projects simultaneously. In fact, cloud hosting plans are among those we offer in our <a target="_blank" href="{link}">agency hosting</a> services.</p><p>With hPanel, you can access your clients’ accounts from your own, organise websites with custom tags, invite your team to collaborate on projects, and monitor everything that matters to you: site security, performance, and more.</p>`,"faq.answer.cloud-hosting.how-to-migrate":`<p><a target="_blank" href="{link}">Migrating your website to Hostinger</a> is free and easy. Simply secure your cloud hosting plan, submit a migration request, and move as many websites as you want. Your website will still be online during the migration process, and we’ll help you prepare for DNS propagation to minimise downtime.</p>`,"faq.answer.cloud-hosting.price":`<p>Depending on the size of your online project, you can buy one of the following cloud plans:</p><ul><li><b>Cloud Startup – {economyPrice}/month for the 48-month plan</b></li><li><b>Cloud Professional – {professionalPrice}/month for the 48-month plan</b></li><li><b>Cloud Enterprise – {enterprisePrice}/month for the 48-month plan</b></li></ul><p>Every cloud hosting package includes a free domain, free SSL certificates, free domain-based emails, and 24/7 priority support. Plus, we offer a 30-day money-back guarantee so you can explore our services without risk.</p><p>If you already have a web hosting plan, upgrading to managed cloud hosting services only takes a few clicks via our user-friendly hPanel. In case you get stuck, our Customer Success agents will be happy to help.</p>`,"faq.answer.cloud-hosting.cloud-vs-traditional":`<p>One notable difference is that cloud server hosting gives you 4x more speed and 20x more resources compared to <a target="_blank" href="{link}">traditional web hosting</a>. As a result, your website will perform at its very best no matter how busy it gets.</p><p>Cloud website hosting also comes with a dedicated IP address, ensuring better protection against security breaches and improved email deliverability. Unlike a shared IP address in traditional web hosting, spam activities performed by other users won’t negatively impact your domain name and branding.</p>`,"faq.answer.cloud-hosting.server-vs-hosting":`<p>A server is basically a physical machine or a computer that stores website files. When you buy a hosting service, you essentially rent space in a server to host your site.</p><p>Now, you can rent the whole physical machine exclusively for your site. It’s called a dedicated server. However, it’s super expensive, and you need advanced technical knowledge to manage the server.</p><p>An easier and more affordable solution is to host multiple websites in one server, which is called shared hosting. Here, server maintenance is handled by the hosting provider, and you’ll get a control panel to manage your account easily.</p><p>But there’s also a downside to this: since you’re sharing server resources with other users, any issues experienced by other sites can directly affect your website too.</p><p>If you want to get the power of a dedicated server and the ease of use of shared hosting, a managed cloud hosting solution is the perfect choice. It gives you a lot more server resources and power than shared hosting, while still providing an intuitive control panel.</p>`,"faq.answer.cloud-hosting.expert-priority-support":`<p>With priority support, your questions will go straight to our cloud hosting experts, instead of the general Customer Success specialists. These technical agents know the ins and outs of cloud hosting, which means you’ll get more accurate answers, faster.</p><p>Our priority support is available 24/7 via live chat, with a median response time of one minute for requests in English. Prefer to speak in your mother tongue? Don’t worry, <a target="_blank" href="{link}">we support 10 other languages</a>, including Spanish, French, Portuguese, Chinese, and Arabic.</p>`,"faq.answer.cloud-hosting.hardware-limits":`<p>To learn what resources our cloud hosting solutions provide, check out these <a target="_blank" href="{link}">parameters and limits for hosting plans</a>. You will find detailed information on the specific limits associated with each plan we offer, so you can make an informed choice based on your website's needs.</p>`,"faq.answer.cloud-hosting.ssd":`<p>We use the NVMe SSD technology in all cloud hosting packages. It’s a storage protocol designed to read, write, and transfer data much faster than traditional solid-state drives (SSD).</p><p>NVMe SSD storage is suitable for projects that require high-speed data access and stable performance, such as ecommerce stores, online course platforms, community forums, travel aggregator sites, and others.</p>`,"faq.question.cloud-hosting.what-is-it":`What is cloud hosting?`,"faq.question.cloud-hosting.why-to-get":`Why should I get cloud hosting services?`,"faq.question.cloud-hosting.how-to-migrate":`How can I migrate my websites to Hostinger’s cloud plan?`,"faq.question.cloud-hosting.price":`How much does cloud hosting cost? How easy is it to upgrade to a cloud plan?`,"faq.question.cloud-hosting.cloud-vs-traditional":`What is the difference between cloud and traditional hosting?`,"faq.question.cloud-hosting.vps-vs-cloud":`What is the difference between VPS and cloud server hosting?`,"faq.question.cloud-hosting.server-vs-hosting":`What's the difference between a server and cloud hosting?`,"faq.question.cloud-hosting.expert-priority-support":`What does expert priority support mean?`,"faq.question.cloud-hosting.hardware-limits":`What are the CPU, RAM, inode, and disk limits of Hostinger plans?`,"faq.question.cloud-hosting.ssd":`Are you using SSD as storage for managed cloud hosting plans?`,"faq.question.cloud-hosting.node-js":`Can I run Node.js on your cloud server?`};export{t as n,n as t};